using System;
using Framework.AI.Core;
using Framework.AI.Perception;
using Framework.Grid;
using Framework.Movement;
using Framework.Parameters;
using Game.AI.Core;
using Game.AI.Parameters;
using Game.Stage;
using UnityEngine;
using UnityEngine.Tilemaps;

namespace Game.Tests
{
    /// <summary>
    /// 敵エージェントの実行コンテキストを検証する。
    /// </summary>
    [DisallowMultipleComponent]
    public sealed class MazeEnemyContextTest : MonoBehaviour
    {
        [Header("テスト設定")]

        [SerializeField]
        [Tooltip("開始時にテストを実行する。")]
        private bool runTestsOnStart = true;

        [Header("テスト用参照")]

        [SerializeField]
        [Tooltip("ステージ生成用の設定済みPrefab。")]
        private MazeStageManager stageManagerPrefab;

        [Header("テスト結果")]

        [SerializeField]
        [Tooltip("成功したテスト件数。")]
        private int passedCount;

        [SerializeField]
        [Tooltip("失敗したテスト件数。")]
        private int failedCount;

        /// <summary>
        /// 予定されているテスト件数。
        /// </summary>
        private const int ExpectedTestCount = 40;

        /// <summary>
        /// テスト用ステージ管理コンポーネント。
        /// </summary>
        private MazeStageManager stageManager;

        /// <summary>
        /// テスト用移動制御コンポーネント。
        /// </summary>
        private GridMovementController movement;

        /// <summary>
        /// テスト用移動オブジェクト。
        /// </summary>
        private GameObject movementObject;

        /// <summary>
        /// テスト用パラメーターセット。
        /// </summary>
        private ParameterSet<MazeEnemyParameter> parameters;

        /// <summary>
        /// テスト対象の敵コンテキスト。
        /// </summary>
        private MazeEnemyContext context;

        /// <summary>
        /// テスト用の初期出現位置。
        /// </summary>
        private Vector2Int spawnPosition;

        /// <summary>
        /// 開始時のテスト実行を制御する。
        /// </summary>
        private void Start()
        {
            if (runTestsOnStart)
            {
                RunAllTests();
            }
        }

        /// <summary>
        /// すべてのテストを実行する。
        /// </summary>
        [ContextMenu("すべてのテストを実行")]
        public void RunAllTests()
        {
            passedCount = 0;
            failedCount = 0;

            try
            {
                Setup();

                TestInitialization();
                TestSpatialInformation();
                TestParameterSynchronization();
                TestMemory();
                TestIndependence();
                TestLifecycle();
            }
            catch (Exception exception)
            {
                failedCount++;

                Debug.LogException(exception, this);
            }
            finally
            {
                Cleanup();
            }

            Debug.Log(
                $"【MazeEnemyContext テスト結果】\n" +
                $"成功：{passedCount}\n" +
                $"失敗：{failedCount}\n" +
                (passedCount == ExpectedTestCount &&
                 failedCount == 0
                    ? "すべてのテストに成功しました。"
                    : "失敗または未実行のテストがあります。"),
                this);
        }

        /// <summary>
        /// テスト用の依存関係を生成する。
        /// </summary>
        private void Setup()
        {
            if (stageManagerPrefab == null)
            {
                throw new InvalidOperationException(
                    "テスト用StageManager Prefabが未設定です。");
            }

            // ゲーム本体とは独立したステージを生成する。
            stageManager = Instantiate(stageManagerPrefab);

            stageManager.name =
                "MazeEnemyContext_Stage_Test";

            if (!stageManager.GenerateStage())
            {
                throw new InvalidOperationException(
                    "テスト用ステージの生成に失敗しました。");
            }

            spawnPosition =
                stageManager.StageResult.PlayerSpawnPosition;

            // テスト専用の移動制御を生成する。
            movementObject = new GameObject(
                "MazeEnemyContext_Movement_Test");

            movement =
                movementObject.AddComponent<
                    GridMovementController>();

            movement.AutoUpdate = false;

            movement.Initialize(
                stageManager.CoordinateConverter,
                stageManager.IsWalkable,
                spawnPosition);

            parameters =
                MazeEnemyParameterCatalog.CreateParameterSet();

            var agent =
                new AgentContext<MazeEnemyParameter>(
                    "TestEnemy",
                    parameters);

            context = new MazeEnemyContext(
                agent,
                stageManager,
                movement,
                spawnPosition);
        }

        /// <summary>
        /// 初期化状態と個体情報を検証する。
        /// </summary>
        private void TestInitialization()
        {
            bool validPassed = context.IsValid;
            Debug.Assert(validPassed, "初期化状態", this);
            Check(validPassed, "初期化状態");

            bool idPassed =
                context.Id != Guid.Empty &&
                context.Id == context.Agent.Id;
            Debug.Assert(idPassed, "個体識別子", this);
            Check(idPassed, "個体識別子");

            bool namePassed = context.Name == "TestEnemy";
            Debug.Assert(namePassed, "個体名", this);
            Check(namePassed, "個体名");

            bool parameterPassed = ReferenceEquals(
                context.Parameters, parameters);
            Debug.Assert(parameterPassed, "パラメーター参照", this);
            Check(parameterPassed, "パラメーター参照");

            bool stagePassed = ReferenceEquals(
                context.StageManager, stageManager);
            Debug.Assert(stagePassed, "ステージ参照", this);
            Check(stagePassed, "ステージ参照");

            bool mapPassed = ReferenceEquals(
                context.Map, stageManager.Map);
            Debug.Assert(mapPassed, "迷路データ参照", this);
            Check(mapPassed, "迷路データ参照");

            bool movementPassed = ReferenceEquals(
                context.Movement, movement);
            Debug.Assert(movementPassed, "移動制御参照", this);
            Check(movementPassed, "移動制御参照");

            bool invalidPassed =
                Throws<ArgumentNullException>(() =>
                    new MazeEnemyContext(
                        null,
                        stageManager,
                        movement,
                        spawnPosition));
            Debug.Assert(invalidPassed, "不正な初期化の拒否", this);
            Check(invalidPassed, "不正な初期化の拒否");
        }

        /// <summary>
        /// 空間情報と縄張りの設定を検証する。
        /// </summary>
        private void TestSpatialInformation()
        {
            bool spawnPassed =
                context.SpawnPosition == spawnPosition &&
                context.CurrentCell == spawnPosition;
            Debug.Assert(spawnPassed, "初期出現位置", this);
            Check(spawnPassed, "初期出現位置");

            bool centerPassed =
                context.IsAtCellCenter &&
                !context.IsTraversing;
            Debug.Assert(centerPassed, "セル中心の判定", this);
            Check(centerPassed, "セル中心の判定");

            bool territoryPassed =
                context.TerritoryCenter == spawnPosition;
            Debug.Assert(territoryPassed, "縄張りの初期位置", this);
            Check(territoryPassed, "縄張りの初期位置");

            Vector2Int nextPosition =
                FindOtherWalkableCell();

            bool changePassed =
                context.TrySetTerritoryCenter(nextPosition) &&
                context.TerritoryCenter == nextPosition;
            Debug.Assert(changePassed, "縄張り中心の変更", this);
            Check(changePassed, "縄張り中心の変更");

            bool invalidPassed =
                !context.TrySetTerritoryCenter(
                    new Vector2Int(-1, -1)) &&
                context.TerritoryCenter == nextPosition;
            Debug.Assert(invalidPassed, "不正な縄張り設定の拒否", this);
            Check(invalidPassed, "不正な縄張り設定の拒否");

            bool resetPassed =
                context.ResetTerritoryCenter() &&
                context.TerritoryCenter == spawnPosition;
            Debug.Assert(resetPassed, "縄張り中心のリセット", this);
            Check(resetPassed, "縄張り中心のリセット");
        }

        /// <summary>
        /// パラメーターと認識機能の連携を検証する。
        /// </summary>
        private void TestParameterSynchronization()
        {
            bool valuePassed = NearlyEqual(
                context.GetParameterValue(
                    MazeEnemyParameter.MoveSpeed),
                3.5f);
            Debug.Assert(valuePassed, "パラメーター取得", this);
            Check(valuePassed, "パラメーター取得");

            bool normalizedPassed = NearlyEqual(
                context.GetNormalizedParameterValue(
                    MazeEnemyParameter.Aggression),
                0.5f);
            Debug.Assert(normalizedPassed, "正規化値の取得", this);
            Check(normalizedPassed, "正規化値の取得");

            bool initialRangePassed =
                NearlyEqual(context.VisionSensor.Range, 6f) &&
                NearlyEqual(
                    context.ThreatVisionSensor.Range, 8f);
            Debug.Assert(initialRangePassed, "初期認識距離", this);
            Check(initialRangePassed, "初期認識距離");

            parameters.SetBaseValue(
                MazeEnemyParameter.DetectionRange, 4f);

            bool rangePassed = NearlyEqual(
                context.VisionSensor.Range, 4f);
            Debug.Assert(rangePassed, "認識距離の自動反映", this);
            Check(rangePassed, "認識距離の自動反映");

            parameters.SetBaseValue(
                MazeEnemyParameter.ThreatDetectionRange, 10f);

            bool threatPassed =
                NearlyEqual(
                    context.ThreatVisionSensor.Range, 10f) &&
                NearlyEqual(context.VisionSensor.Range, 4f);
            Debug.Assert(threatPassed, "脅威認識距離の独立性", this);
            Check(threatPassed, "脅威認識距離の独立性");

            parameters.SetBaseValue(
                MazeEnemyParameter.MemoryDuration, 12f);

            bool durationPassed =
                Math.Abs(
                    context.PerceptionMemory.RetentionDuration -
                    12d) <= 0.0001d;
            Debug.Assert(durationPassed, "記憶時間の自動反映", this);
            Check(durationPassed, "記憶時間の自動反映");

            parameters.ResetAll();
        }

        /// <summary>
        /// 認識対象の記憶と訪問履歴を検証する。
        /// </summary>
        private void TestMemory()
        {
            bool initialVisitPassed =
                context.SpatialMemory.HasVisited(
                    spawnPosition);
            Debug.Assert(initialVisitPassed, "初期位置の訪問記録", this);
            Check(initialVisitPassed, "初期位置の訪問記録");

            Vector2Int otherPosition =
                FindOtherWalkableCell();

            bool unvisitedPassed = NearlyEqual(
                context.GetUnvisitedScore(otherPosition),
                1f);
            Debug.Assert(unvisitedPassed, "未訪問セルの評価", this);
            Check(unvisitedPassed, "未訪問セルの評価");

            bool visitPassed =
                context.RecordVisit(otherPosition) &&
                context.SpatialMemory.HasVisited(otherPosition);
            Debug.Assert(visitPassed, "訪問履歴の登録", this);
            Check(visitPassed, "訪問履歴の登録");

            bool duplicatePassed =
                !context.RecordVisit(otherPosition) &&
                context.SpatialMemory.GetVisitCount(
                    otherPosition) == 1;
            Debug.Assert(duplicatePassed, "重複訪問の防止", this);
            Check(duplicatePassed, "重複訪問の防止");

            Guid targetId = Guid.NewGuid();

            var stimulus =
                new PerceptionStimulus<Vector2Int>(
                    targetId,
                    PerceptionType.Sight,
                    otherPosition,
                    1f,
                    context.CurrentTime);

            bool rememberPassed =
                context.RememberObservation(stimulus);
            Debug.Assert(rememberPassed, "認識情報の記憶", this);
            Check(rememberPassed, "認識情報の記憶");

            bool recallPassed =
                context.TryRecallObservation(
                    targetId,
                    out var recalled,
                    out float confidence) &&
                recalled.Position == otherPosition &&
                NearlyEqual(confidence, 1f);
            Debug.Assert(recallPassed, "認識情報の取得", this);
            Check(recallPassed, "認識情報の取得");

            parameters.SetBaseValue(
                MazeEnemyParameter.MemoryDuration, 0f);

            bool disabledPassed =
                !context.IsPerceptionMemoryEnabled &&
                context.PerceptionMemory.Count == 0 &&
                !context.RememberObservation(stimulus) &&
                !context.TryRecallObservation(
                    targetId, out _, out _);
            Debug.Assert(disabledPassed, "記憶機能の無効化", this);
            Check(disabledPassed, "記憶機能の無効化");

            parameters.ResetAll();

            context.ClearMemories();

            bool clearPassed =
                context.PerceptionMemory.Count == 0 &&
                context.SpatialMemory.VisitedPositionCount == 1 &&
                context.SpatialMemory.HasVisited(spawnPosition);
            Debug.Assert(clearPassed, "記憶の初期化", this);
            Check(clearPassed, "記憶の初期化");
        }

        /// <summary>
        /// 複数の敵コンテキストの独立性を検証する。
        /// </summary>
        private void TestIndependence()
        {
            var secondObject =
                new GameObject("MazeEnemyContext_Second_Test");

            try
            {
                var secondMovement =
                    secondObject.AddComponent<
                        GridMovementController>();

                secondMovement.AutoUpdate = false;

                secondMovement.Initialize(
                    stageManager.CoordinateConverter,
                    stageManager.IsWalkable,
                    spawnPosition);

                using (var secondParameters =
                    MazeEnemyParameterCatalog.CreateParameterSet())
                {
                    var secondAgent =
                        new AgentContext<MazeEnemyParameter>(
                            "SecondEnemy",
                            secondParameters);

                    using (var secondContext =
                        new MazeEnemyContext(
                            secondAgent,
                            stageManager,
                            secondMovement,
                            spawnPosition))
                    {
                        bool idPassed =
                            context.Id != secondContext.Id;
                        Debug.Assert(idPassed, "個体識別子の独立性", this);
                        Check(idPassed, "個体識別子の独立性");

                        bool mapPassed = ReferenceEquals(
                            context.Map,
                            secondContext.Map);
                        Debug.Assert(mapPassed, "迷路データの共有", this);
                        Check(mapPassed, "迷路データの共有");

                        parameters.SetBaseValue(
                            MazeEnemyParameter.DetectionRange,
                            2f);

                        bool sensorPassed =
                            NearlyEqual(
                                context.VisionSensor.Range, 2f) &&
                            NearlyEqual(
                                secondContext.VisionSensor.Range, 6f);
                        Debug.Assert(sensorPassed, "認識能力の独立性", this);
                        Check(sensorPassed, "認識能力の独立性");

                        Vector2Int position =
                            FindOtherWalkableCell();

                        context.RecordVisit(position);

                        bool memoryPassed =
                            context.SpatialMemory.HasVisited(
                                position) &&
                            !secondContext.SpatialMemory.HasVisited(
                                position) &&
                            !ReferenceEquals(
                                context.PerceptionMemory,
                                secondContext.PerceptionMemory);
                        Debug.Assert(memoryPassed, "記憶領域の独立性", this);
                        Check(memoryPassed, "記憶領域の独立性");
                    }
                }
            }
            finally
            {
                secondObject.SetActive(false);

                Destroy(secondObject);
            }

            parameters.ResetAll();
        }

        /// <summary>
        /// ステージ状態とコンテキストの解放を検証する。
        /// </summary>
        private void TestLifecycle()
        {
            bool readyPassed =
                context.IsValid &&
                !context.CanAct;
            Debug.Assert(readyPassed, "開始前の行動制限", this);
            Check(readyPassed, "開始前の行動制限");

            bool startPassed =
                stageManager.StartStage() &&
                context.CanAct;
            Debug.Assert(startPassed, "開始後の行動許可", this);
            Check(startPassed, "開始後の行動許可");

            bool pausePassed =
                stageManager.PauseStage() &&
                !context.CanAct &&
                context.IsValid;
            Debug.Assert(pausePassed, "一時停止中の行動制限", this);
            Check(pausePassed, "一時停止中の行動制限");

            bool resumePassed =
                stageManager.ResumeStage() &&
                context.CanAct;
            Debug.Assert(resumePassed, "再開後の行動許可", this);
            Check(resumePassed, "再開後の行動許可");

            movement.Pause();

            bool movementPausePassed =
                !context.CanAct &&
                context.IsValid;
            Debug.Assert(movementPausePassed, "移動停止中の行動制限", this);
            Check(movementPausePassed, "移動停止中の行動制限");

            movement.Resume();

            stageManager.ClearStage();

            bool invalidStagePassed =
                !context.IsValid &&
                !context.CanAct &&
                !context.IsWalkable(spawnPosition);
            Debug.Assert(invalidStagePassed, "ステージ解放時の無効化", this);
            Check(invalidStagePassed, "ステージ解放時の無効化");

            float previousRange =
                context.VisionSensor.Range;

            context.Dispose();

            parameters.SetBaseValue(
                MazeEnemyParameter.DetectionRange, 1f);

            bool disposePassed =
                context.IsDisposed &&
                !context.IsValid &&
                !parameters.IsDisposed &&
                context.SpatialMemory.VisitedPositionCount == 0 &&
                context.PerceptionMemory.Count == 0 &&
                NearlyEqual(
                    context.VisionSensor.Range,
                    previousRange);
            Debug.Assert(disposePassed, "解放と購読解除", this);
            Check(disposePassed, "解放と購読解除");

            context.Dispose();

            bool disposedAccessPassed =
                Throws<ObjectDisposedException>(() =>
                    context.GetParameterValue(
                        MazeEnemyParameter.MoveSpeed));
            Debug.Assert(disposedAccessPassed, "解放後のアクセス制限", this);
            Check(disposedAccessPassed, "解放後のアクセス制限");
        }

        /// <summary>
        /// 初期位置以外の通行可能セルを取得する。
        /// </summary>
        /// <returns>通行可能なグリッド座標</returns>
        private Vector2Int FindOtherWalkableCell()
        {
            foreach (Vector2Int position in
                stageManager.Map.GetPositions())
            {
                if (position != spawnPosition &&
                    stageManager.IsWalkable(position))
                {
                    return position;
                }
            }

            throw new InvalidOperationException(
                "テスト用の通行可能セルが見つかりません。");
        }

        /// <summary>
        /// テストで生成したリソースを解放する。
        /// </summary>
        private void Cleanup()
        {
            if (context != null)
            {
                context.Dispose();
                context = null;
            }

            if (parameters != null)
            {
                parameters.Dispose();
                parameters = null;
            }

            if (movementObject != null)
            {
                movementObject.SetActive(false);

                Destroy(movementObject);

                movementObject = null;
                movement = null;
            }

            if (stageManager != null)
            {
                stageManager.ClearStage();

                stageManager.gameObject.SetActive(false);

                Destroy(stageManager.gameObject);

                stageManager = null;
            }
        }

        /// <summary>
        /// 浮動小数点数を許容誤差付きで比較する。
        /// </summary>
        /// <param name="first">比較する値</param>
        /// <param name="second">比較対象の値</param>
        /// <returns>十分に近い場合はtrue</returns>
        private bool NearlyEqual(float first, float second)
        {
            return Mathf.Abs(first - second) <= 0.0001f;
        }

        /// <summary>
        /// 期待する例外が発生するか検証する。
        /// </summary>
        /// <typeparam name="TException">期待する例外型</typeparam>
        /// <param name="action">検証対象の処理</param>
        /// <returns>期待する例外が発生した場合はtrue</returns>
        private bool Throws<TException>(Action action)
            where TException : Exception
        {
            try
            {
                action();
            }
            catch (Exception exception)
            {
                if (exception.GetType() == typeof(TException))
                {
                    return true;
                }

                throw;
            }

            return false;
        }

        /// <summary>
        /// 個別のテスト結果を出力して集計する。
        /// </summary>
        /// <param name="passed">成功判定</param>
        /// <param name="testName">テスト名</param>
        private void Check(bool passed, string testName)
        {
            if (passed)
            {
                passedCount++;

                Debug.Log(
                    $"<color=#00CC66>【成功】</color> {testName}",
                    this);
            }
            else
            {
                failedCount++;

                Debug.LogError(
                    $"【失敗】{testName}",
                    this);
            }
        }
    }
}
